import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

/**
 * Blob Animation
 *
 * A morphing blob in pure CSS. The shape is a box whose eight-value
 * border-radius changes between four keyframes, so the browser interpolates
 * an organic outline with no SVG path morphing and no JavaScript per frame.
 * The four radii live in custom properties, so every blob runs the same
 * shared keyframes with its own shape, generated from a `seed`.
 *
 * Variants:
 * - solid: a gradient blob with a soft highlight and an inner shade, so it
 *   reads as a lit, rounded object rather than a flat sticker.
 * - soft: the same gradient blurred into a glow, for backgrounds.
 * - outline: a gradient ring that morphs with the shape.
 * - image: a photo masked by the blob, which stays upright while the
 *   outline turns, for portfolio heroes and avatars.
 *
 * `wobble` sets how far the outline strays from a circle. `rotate` turns the
 * whole shape slowly, which hides the four-keyframe rhythm. Reduced motion
 * holds the first shape still. The stylesheet renders with the component,
 * so server-rendered pages are styled before hydration, and React keeps one
 * copy in <head> however many blobs are on the page. No global CSS or
 * dependencies.
 */

export type BlobAnimationVariant = "solid" | "soft" | "outline" | "image";

export interface BlobAnimationProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "color"> {
  /** Look of the blob. Default solid, or image when `src` is set. */
  variant?: BlobAnimationVariant;
  /** Gradient colors, two or more CSS colors. */
  colors?: string[];
  /** Width and height in pixels, or any CSS length. Default 320. */
  size?: number | string;
  /** Seconds for one full morph cycle. Default 10. */
  duration?: number;
  /** How far the outline strays from a circle, from 0 to 1. Default 0.6. */
  wobble?: number;
  /** Turns the shape slowly while it morphs. Default true. */
  rotate?: boolean;
  /** Picks a different shape. Same seed, same blob. Default 1. */
  seed?: number;
  /** Ring thickness in pixels for the outline variant. Default 2. */
  thickness?: number;
  /** Image for the image variant. */
  src?: string;
  /** Alt text for the image. Leave empty for a decorative image. */
  alt?: string;
  children?: React.ReactNode;
}

const STYLE_ID = "wensity-blob-animation";
const DEFAULT_COLORS = ["#ff1100", "#f97316", "#fbbf24"];

const CSS = `
@keyframes wba-morph {
  0%, 100% { border-radius: var(--wba-r0); }
  25% { border-radius: var(--wba-r1); }
  50% { border-radius: var(--wba-r2); }
  75% { border-radius: var(--wba-r3); }
}
@keyframes wba-turn { to { transform: rotate(360deg); } }
@keyframes wba-unturn { to { transform: rotate(-360deg); } }
.wba {
  position: relative;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: var(--wba-size);
  height: var(--wba-size);
}
.wba-turn {
  position: absolute;
  inset: 0;
}
.wba[data-rotate="true"] .wba-turn { animation: wba-turn calc(var(--wba-d) * 3) linear infinite; }
.wba-shape {
  position: absolute;
  inset: 0;
  overflow: hidden;
  border-radius: var(--wba-r0);
  animation: wba-morph var(--wba-d) ease-in-out infinite;
}
.wba[data-variant="solid"] .wba-shape {
  background: linear-gradient(135deg, var(--wba-c1), var(--wba-c2), var(--wba-c3));
  box-shadow:
    inset -18px -26px 48px rgba(0, 0, 0, 0.22),
    inset 14px 18px 36px rgba(255, 255, 255, 0.18);
}
.wba[data-variant="solid"] .wba-shape::after {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(60% 45% at 32% 24%, rgba(255, 255, 255, 0.38), transparent 70%);
  mix-blend-mode: soft-light;
}
.wba[data-variant="soft"] .wba-shape {
  background: linear-gradient(135deg, var(--wba-c1), var(--wba-c2), var(--wba-c3));
  filter: blur(calc(var(--wba-size) * 0.09));
  opacity: 0.85;
  overflow: visible;
}
.wba[data-variant="outline"] .wba-shape {
  padding: var(--wba-w);
  background: linear-gradient(135deg, var(--wba-c1), var(--wba-c2), var(--wba-c3));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask: linear-gradient(#000 0 0) content-box exclude, linear-gradient(#000 0 0);
}
.wba[data-variant="image"] .wba-shape {
  background: linear-gradient(135deg, var(--wba-c1), var(--wba-c2), var(--wba-c3));
}
.wba-img {
  position: absolute;
  inset: -12%;
  width: 124%;
  height: 124%;
  max-width: none;
  object-fit: cover;
}
.wba[data-rotate="true"] .wba-img { animation: wba-unturn calc(var(--wba-d) * 3) linear infinite; }
.wba-content {
  position: relative;
  z-index: 1;
}
@media (prefers-reduced-motion: reduce) {
  .wba .wba-turn,
  .wba .wba-shape,
  .wba .wba-img { animation: none !important; }
}
`;

/** Small seeded random, so a seed always gives the same blob on server and client. */
function seeded(seed: number) {
  let t = Math.floor(seed * 9973) >>> 0;
  return () => {
    t = (t + 0x6d2b79f5) >>> 0;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Four border-radius shapes. Each corner gets a horizontal and a vertical
 * radius, and opposite edges add up to 100%, so the outline stays closed and
 * smooth instead of pinching into corners.
 */
function blobShapes(seed: number, wobble: number) {
  const random = seeded(seed);
  const spread = 32 * Math.min(1, Math.max(0, wobble));
  const pick = () => Math.round(50 + (random() * 2 - 1) * spread);
  return Array.from({ length: 4 }, () => {
    const top = pick();
    const bottom = pick();
    const left = pick();
    const right = pick();
    return `${top}% ${100 - top}% ${100 - bottom}% ${bottom}% / ${left}% ${right}% ${100 - right}% ${100 - left}%`;
  });
}

export function BlobAnimation({
  variant,
  colors = DEFAULT_COLORS,
  size = 320,
  duration = 10,
  wobble = 0.6,
  rotate = true,
  seed = 1,
  thickness = 2,
  src,
  alt = "",
  className,
  style,
  children,
  ...props
}: BlobAnimationProps) {
  const look: BlobAnimationVariant = variant ?? (src ? "image" : "solid");
  const palette = colors.length > 0 ? colors : DEFAULT_COLORS;
  const [c1, c2 = c1, c3 = c2] = palette;
  const shapes = React.useMemo(() => blobShapes(seed, wobble), [seed, wobble]);

  const vars = {
    "--wba-c1": c1,
    "--wba-c2": c2,
    "--wba-c3": c3,
    "--wba-size": typeof size === "number" ? `${size}px` : size,
    "--wba-d": `${Math.max(1, duration)}s`,
    "--wba-w": `${thickness}px`,
    "--wba-r0": shapes[0],
    "--wba-r1": shapes[1],
    "--wba-r2": shapes[2],
    "--wba-r3": shapes[3],
  } as React.CSSProperties;

  return (
    <div
      {...props}
      data-variant={look}
      data-rotate={rotate ? "true" : "false"}
      className={cn("wba", className)}
      style={{ ...vars, ...style }}
    >
      {/* Rendered with the markup, so server-rendered pages are styled before
          hydration. React hoists it into <head> and emits it once per page. */}
      <style href={STYLE_ID} precedence="default">
        {CSS}
      </style>
      <div aria-hidden={look !== "image" || !alt} className="wba-turn">
        <div className="wba-shape">
          {look === "image" && src ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img className="wba-img" src={src} alt={alt} draggable={false} />
          ) : null}
        </div>
      </div>
      {children ? <div className="wba-content">{children}</div> : null}
    </div>
  );
}
